import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load brushed metal texture for card background
  const metalTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry (512×320 atlas region → 1.6 aspect ratio)
  const geometry = new THREE.PlaneGeometry(512 / 320, 1);

  // Create material using TSL nodes
  const colorNode = texture(metalTexture);
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = colorNode;

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text "Collection 2" via fontAtlas
  const textContent = config.textContent || {};
  const textMesh = ctx.fontAtlas.createText({
    text: textContent.text || 'Collection 2',
    font: textContent.font || 'Lora',
    size: textContent.size || 0.34,
    weight: textContent.weight || 400,
    color: textContent.color !== undefined ? textContent.color : 0xe8ecf2,
    anchor: 'center',
  });

  // Position text on top of plane
  textMesh.position.z = 0.01;
  group.add(textMesh);

  // Apply scene placement
  group.position.set(0, 1, 0.06);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalTexture.dispose();
  };

  return group;
}
